def is_power_of_5(x):
    """Checks if a positive integer x is a power of 5."""
    if x <= 0:
        return False
    if x == 1:
        return True

    # Repeatedly divide by 5 and check for remainder
    while x > 1:
        if x % 5 != 0:
            return False
        x //= 5
    return x == 1

results = []
for n in range(3, 16):
    X = 2**n - 3
    if is_power_of_5(X):
        # Find k such that 5^k = X
        k = 0
        temp_X = X
        while temp_X > 0:
            if temp_X == 1:
                break
            if temp_X % 5 != 0:
                # Should not happen if is_power_of_5 passed, but good practice
                k = -1 
                break
            temp_X //= 5
            k += 1

        if k >= 0:
            power_of_5 = 5**k
            results.append((n, power_of_5))

print("Found pairs (n, 5^k):")
for n, power_of_5 in results:
    print(f"n={n}, 2^n - 3 = {power_of_5} = 5^{int(round(math.log(power_of_5, 5)))}")

