def is_power_of_5(x):
    """Checks if a positive integer x is a power of 5."""
    if x <= 0:
        return False
    if x == 1:
        return True

    # Repeatedly divide by 5 and check for remainder
    temp_x = x
    while temp_x > 1:
        if temp_x % 5 != 0:
            return False
        temp_x //= 5
    return temp_x == 1

results = []
for n in range(3, 16):
