import math
def is_power_of_5(num):
    if num <= 0:
        return False
    return num % 5 == 0 and math.log(num, 5).is_integer()

solutions = []
# Check odd n from 9 up to 30
for n in range(9, 31, 2):
    val = (2**n) - 3
    if is_power_of_5(val):
        k = int(math.log(val, 5))
        solutions.append((n, k))

print(f"Solutions found for odd n up to 30: {solutions}")
